package in.tucor.api.auth; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface UserRepository extends JpaRepository<User,UUID>{@org.springframework.data.jpa.repository.Lock(jakarta.persistence.LockModeType.PESSIMISTIC_WRITE) @org.springframework.data.jpa.repository.Query("select u from User u where u.role=in.tucor.api.auth.Role.ADMIN order by u.id") List<User> findAdminsForUpdate();List<User> findByRoleNotAndEmailContainingIgnoreCase(Role role,String query,org.springframework.data.domain.Pageable page);Optional<User> findByEmailIgnoreCase(String email);@org.springframework.data.jpa.repository.Lock(jakarta.persistence.LockModeType.PESSIMISTIC_WRITE) @org.springframework.data.jpa.repository.Query("select u from User u where lower(u.email)=lower(:email)") Optional<User> findByEmailForUpdate(String email);@org.springframework.data.jpa.repository.Lock(jakarta.persistence.LockModeType.PESSIMISTIC_WRITE) @org.springframework.data.jpa.repository.Query("select u from User u where u.id=:id") Optional<User> findByIdForUpdate(UUID id);}